eltharus,\n        uldaman,\n        brackenhideHollow,\n        murozondsRise,\n        misc,\n        vault,\n        sepulcher,\n        nathria,\n        nerubarPalace,\n        araKara,\n        cityOfThreads,\n        tazavesh,\n        theaterOfPain,\n        necroticWake,\n        mistsOfTirnaScithe,\n        hallsOfAtonement,\n        deOtherSide,\n        plaguefall,\n        sanguineDepths,\n        grimBatol,\n        siegeOfBoralus,\n        mechagon,\n    }\n    \n    for i = 1, #maps do\n        local map = maps[i]\n        \n        for id, priority in pairs(map) do\n            modTable.npcIDs[id] = priority\n        end\n    end\n    \n    ---@param unit string\n    ---@return number|nil\n    function modTable.parseGUID(unit)\n        local guid = UnitGUID(unit)\n        \n        if not guid then\n            return nil\n        end\n        \n        local id = select(6, strsplit(\"-\", guid))\n        \n        return id and tonumber(id) or nil\n    end\n    \n    -- do nothing while spiteful is disabled\n    -- when updating this, also update Nameplate Updated and Leave Combat\n    \n    -- ---@param id number\n    -- ---@return boolean\n    -- function modTable.isSpiteful(id)\n    --     return tonumber(id) == 174773\n    -- end\n    \n    -- ---@param unitId string\n    -- ---@return boolean\n    -- function modTable.spitefulTargetsPlayer(unitId)\n    --     local targetName = UnitName(unitId .. \"target\")\n    \n    --     if not targetName then\n    --         return false\n    --     end\n    \n    --     return UnitIsUnit(targetName, \"player\")\n    -- end\nend",
["Nameplate Added"] = "function (self, unitId, unitFrame, envTable, modTable)\n    if not modTable.config.scale then\n        return\n    end\n    \n    local npcID = unitFrame.namePlateNpcId or modTable.parseGUID(unitId)\n    \n    if not npcID then\n        return\n    end\n    \n    local scale = modTable.npcIDs[npcID]\n    \n    if scale then\n        Plater.SetNameplateScale(unitFrame, scale)\n    end\nend",
